import * as React from "react";
import type { Meta, StoryObj } from "@storybook/react-vite";
import { ThemeControl, ThemeProvider, useTheme } from "@creator-signal/ui/client";
import {
  THEME_STORAGE_KEY,
  createThemeRuntime,
  resolveTheme,
  type ThemePreference
} from "@creator-signal/design-system/theme-runtime";

function createMemoryStorage(initialPreference: ThemePreference) {
  const values = new Map<string, string>();
  if (initialPreference !== "system") values.set(THEME_STORAGE_KEY, initialPreference);
  return {
    getItem(key: string) { return values.get(key) ?? null; },
    setItem(key: string, value: string) { values.set(key, value); },
    removeItem(key: string) { values.delete(key); }
  };
}

function ThemePanel() {
  const { preference, resolvedTheme } = useTheme();

  return (
    <main className="cs-story-shell">
      <p className="cs-story-eyebrow">Theme runtime · #878</p>
      <h1 className="cs-story-title">System, light and dark from one semantic contract</h1>
      <p className="cs-story-lede">
        Change the real shared theme preference below. The control persists only a bounded preference, while the runtime resolves system colour scheme and applies the same semantic token API in either theme.
      </p>

      <section className="cs-story-section" aria-labelledby="runtime-heading">
        <div className="cs-story-section-header">
          <div>
            <p className="cs-story-eyebrow">Interactive contract</p>
            <h2 id="runtime-heading">Theme preference</h2>
          </div>
          <div className="cs-theme-state" aria-label="Current theme state">
            <span>Preference <strong>{preference}</strong></span>
            <span>Resolved <strong>{resolvedTheme}</strong></span>
          </div>
        </div>

        <ThemeControl className="cs-theme-control" label="Appearance" />
      </section>

      <section className="cs-story-section" aria-labelledby="semantic-theme-heading">
        <p className="cs-story-eyebrow">Semantic equivalence</p>
        <h2 id="semantic-theme-heading">The roles stay the same when the colours change</h2>
        <div className="cs-theme-grid">
          <article className="cs-theme-card">
            <span className="cs-type-label">Raised surface</span>
            <h3 className="cs-type-heading3">A creator decision</h3>
            <p className="cs-type-body">Your repeat-customer revenue is stronger than the previous 30 days. Consider featuring the designs that brought customers back.</p>
            <button className="cs-theme-primary" type="button">Review the signal</button>
          </article>
          <article className="cs-theme-card cs-theme-subtle">
            <span className="cs-type-label">Native controls</span>
            <label className="cs-theme-field">
              <span>Reporting period</span>
              <select defaultValue="30"><option value="7">Last 7 days</option><option value="30">Last 30 days</option></select>
            </label>
            <label className="cs-theme-field">
              <span>Workspace note</span>
              <input defaultValue="Spring collection review" />
            </label>
            <label className="cs-theme-check"><input type="checkbox" defaultChecked /> Include repeat customers</label>
          </article>
        </div>
      </section>

      <section className="cs-story-section" aria-labelledby="meaning-heading">
        <p className="cs-story-eyebrow">Meaning survives theme changes</p>
        <h2 id="meaning-heading">Status is never colour-only</h2>
        <div className="cs-status-grid">
          <article className="cs-status-card cs-status-success"><span className="cs-status-icon" aria-hidden="true">✓</span><div><strong>Success</strong><p>Import completed.</p></div></article>
          <article className="cs-status-card cs-status-warning"><span className="cs-status-icon" aria-hidden="true">!</span><div><strong>Warning</strong><p>Two rows need review.</p></div></article>
          <article className="cs-status-card cs-status-error"><span className="cs-status-icon" aria-hidden="true">×</span><div><strong>Error</strong><p>The statement could not be saved.</p></div></article>
          <article className="cs-status-card cs-status-info"><span className="cs-status-icon" aria-hidden="true">i</span><div><strong>Information</strong><p>Marketplace data was updated today.</p></div></article>
        </div>
      </section>

      <section className="cs-story-section" aria-labelledby="resilience-heading">
        <p className="cs-story-eyebrow">Client resilience</p>
        <h2 id="resilience-heading">Motion, contrast, print and imagery have explicit behaviour</h2>
        <div className="cs-theme-grid">
          <article className="cs-theme-card">
            <strong>Reduced motion</strong>
            <p>Non-essential design-system motion durations collapse to zero when the operating system requests reduced motion.</p>
          </article>
          <article className="cs-theme-card">
            <strong>Forced colours</strong>
            <p>Essential surfaces, controls, text and focus map to system colours rather than fighting high-contrast mode.</p>
          </article>
          <article className="cs-theme-card" data-cs-image-surface>
            <strong>Image surface</strong>
            <div className="cs-theme-image-placeholder" role="img" aria-label="Synthetic design thumbnail placeholder">Design thumbnail</div>
            <p>Images are not automatically inverted in dark mode.</p>
          </article>
          <article className="cs-theme-card">
            <strong>Print</strong>
            <p>Print output resolves to a legible light, high-contrast semantic treatment.</p>
          </article>
        </div>
      </section>
    </main>
  );
}

function ThemeReviewSurface() {
  const { preference, resolvedTheme } = useTheme();
  return (
    <div className="cs-story-root" data-cs-theme={resolvedTheme} data-cs-theme-preference={preference}>
      <ThemePanel />
    </div>
  );
}

function ThemeRuntimeReview({ initialPreference }: { initialPreference: ThemePreference }) {
  const createRuntime = React.useCallback(() => {
    const media = typeof window.matchMedia === "function" ? window.matchMedia("(prefers-color-scheme: dark)") : undefined;
    return createThemeRuntime({
      root: document.documentElement,
      storage: createMemoryStorage(initialPreference),
      ...(media ? { media } : {})
    });
  }, [initialPreference]);

  const initialSnapshot = React.useMemo(() => {
    const systemDark = typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-color-scheme: dark)").matches
      : false;
    return { preference: initialPreference, resolvedTheme: resolveTheme(initialPreference, systemDark) } as const;
  }, [initialPreference]);

  return (
    <ThemeProvider createRuntime={createRuntime} initialSnapshot={initialSnapshot}>
      <ThemeReviewSurface />
    </ThemeProvider>
  );
}

const meta = {
  title: "Foundations/Theme runtime",
  component: ThemeRuntimeReview,
  tags: ["autodocs"],
  parameters: {
    themeRuntimeOwnsTheme: true,
    docs: {
      description: {
        component: "Executable review of the real #878 framework-neutral runtime and narrow React bindings. System follows the browser/OS preference; Light and Dark prove explicit overrides."
      }
    }
  },
  argTypes: {
    initialPreference: {
      control: "select",
      options: ["system", "light", "dark"]
    }
  }
} satisfies Meta<typeof ThemeRuntimeReview>;

export default meta;
type Story = StoryObj<typeof meta>;

export const System: Story = { args: { initialPreference: "system" }, globals: { theme: "system" } };
export const Light: Story = { args: { initialPreference: "light" }, globals: { theme: "light" } };
export const Dark: Story = { args: { initialPreference: "dark" }, globals: { theme: "dark" } };

